// Process AI response
const content = $input.first().json;
const postText = content.response || content.content || content;

// Extract hashtags
const hashtags = ['#AI', '#KnowledgeManagement', '#IntegrateWise', '#DigitalWorkspace', '#Productivity'];

return [{
  json: {
    post: postText + '\n\n' + hashtags.join(' '),
    generatedAt: new Date().toISOString(),
    platform: 'linkedin'
  }
}];
